// Execute with provider
for await (const response of provider.executeChat(providerRequest, {
  debugMode,
  abortController,
  temperature: agentConfig.config?.temperature,
  maxTokens: agentConfig.config?.maxTokens,
})) {
  // Convert provider response to stream response
  const chatRoomMessage = createChatRoomMessage(response, agentId);

  if (chatRoomMessage) {
    // Send as chat room protocol message
    yield {
      type: "claude_json",
      data: {
        type: "chat_room_message",
        message: chatRoomMessage,
        session_id: request.sessionId,
      },
    };
  }

  // Also send original response format for compatibility
  if (response.type === "text") {
    yield {
      type: "claude_json",
      data: {
        type: "assistant",
        content: response.content,
        model: response.metadata?.model,
      },
    };
  } else if (response.type === "done") {
    yield { type: "done" };
    return;
  } else if (response.type === "error") {
    yield { type: "error", error: response.error };
    return;
  }
}

const delegationTool = {
  name: "delegate_task",
  description: "Delegate a task to another agent and receive its result.",
  input_schema: {
    type: "object",
    properties: { agent_id: { type: "string" }, instructions: { type: "string" } },
    required: ["agent_id", "instructions"],
  },
};
const run = async function* (
  currentId: string,
  currentRequest: ProviderChatRequest,
  path: string[]
): AsyncGenerator<StreamResponse, { content: string; error?: string }> {
  const currentProvider = globalRegistry.getProviderForAgent(currentId);
  const config = globalRegistry.getAgent(currentId);
  if (!currentProvider || !config) {
    const error = `Agent '${currentId}' not found or provider not available`;
    yield { type: "error", error };
    return { content: "", error };
  }
  let output = "";
  const context = [...(currentRequest.context || [])];
  for (let round = 0; round < 32; round++) {
    if (abortController.signal.aborted) return { content: output, error: "Request aborted" };
    const calls: Array<{ id: string; input: unknown }> = [];
    let roundText = "";
    try {
      for await (const response of currentProvider.executeChat({
        ...currentRequest,
        ...(context.length ? { context } : {}),
        tools: [delegationTool],
      }, {
        debugMode, abortController,
        temperature: config.config?.temperature,
        maxTokens: config.config?.maxTokens,
      })) {
        if (response.type === "text") {
          const text = response.content || "";
          output += text;
          roundText += text;
          const message = createChatRoomMessage(response, currentId);
          if (message) yield { type: "claude_json", data: { type: "chat_room_message", message, session_id: request.sessionId } };
          yield { type: "claude_json", data: { type: "assistant", content: response.content, model: response.metadata?.model } };
        } else if (response.type === "tool_use" && response.toolName === "delegate_task") {
          const id = response.toolUseId || `delegate-${crypto.randomUUID()}`;
          calls.push({ id, input: response.toolInput });
          yield { type: "claude_json", data: { type: "tool_use", id, name: response.toolName, input: response.toolInput } };
        } else if (response.type === "error") {
          const error = response.error || "Provider failed";
          if (path.length === 1) yield { type: "error", error };
          return { content: output, error };
        } else if (response.type === "image" || response.type === "tool_use") {
          const message = createChatRoomMessage(response, currentId);
          if (message) yield { type: "claude_json", data: { type: "chat_room_message", message, session_id: request.sessionId } };
        }
      }
    } catch (e) {
      const error = e instanceof Error ? e.message : String(e);
      if (path.length === 1) yield { type: "error", error };
      return { content: output, error };
    }
    if (!calls.length) return { content: output };
    const assistantBlocks: unknown[] = [];
    if (roundText) assistantBlocks.push({ type: "text", text: roundText });
    for (const call of calls) assistantBlocks.push({ type: "tool_use", id: call.id, name: "delegate_task", input: call.input });
    context.push({ role: "assistant", content: JSON.stringify(assistantBlocks) });
    for (const call of calls) {
      const input = call.input as { agent_id?: unknown; instructions?: unknown } | null;
      const target = typeof input?.agent_id === "string" ? input.agent_id : "";
      let result: { content: string; error?: string };
      if (!target || typeof input?.instructions !== "string") {
        result = { content: "", error: "Invalid delegation input: agent_id and instructions are required" };
      } else if (path.includes(target)) {
        const error = `Circular delegation detected: ${[...path, target].join(" -> ")}`;
        yield { type: "error", error };
        result = { content: "", error };
      } else {
        const child = run(target, {
          message: input.instructions,
          requestId: request.requestId,
          workingDirectory: globalRegistry.getAgent(target)?.workingDirectory,
        }, [...path, target]);
        while (true) {
          const next = await child.next();
          if (next.done) { result = next.value; break; }
          yield next.value;
        }
      }
      const toolResult = { type: "tool_result", is_error: !!result.error, content: result.error || result.content || "Agent returned no text.", tool_use_id: call.id };
      context.push({ role: "user", content: JSON.stringify(toolResult) });
      yield { type: "claude_json", data: toolResult };
      if (abortController.signal.aborted) return { content: output, error: "Request aborted" };
    }
  }
  return { content: output, error: "Delegation round limit exceeded" };
};
const execution = run(agentId, providerRequest, [agentId]);
while (true) {
  const next = await execution.next();
  if (next.done) {
    if (!next.value.error) yield { type: "done" };
    else if (next.value.error === "Delegation round limit exceeded") yield { type: "error", error: next.value.error };
    return;
  }
  yield next.value;
}
